SET search_path TO payments; CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY, user_id UUID NOT NULL, subscription_id UUID REFERENCES subscriptions(id), amount DECIMAL(10,2) NOT NULL, currency VARCHAR(3) NOT NULL DEFAULT 'CAD', status VARCHAR(20) NOT NULL, description VARCHAR(255), provider VARCHAR(50), provider_transaction_id VARCHAR(255), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
